        license_allowlist=(
            policy.license_allowlist if policy is not None else ()
        ),
        license_spdx_id=(
            license_record.spdx_id if license_record is not None else None
        ),
    )

    return _json_response(
        start_response,
        "200 OK",
        {"id": raw_id, "score": score, "level": risk_level(score)},
        trailing_newline=True,
    )


